/**
 * Shapes of the checked-in library audit files in this directory:
 *
 * - `census_snapshot.json`: which TEI markup each Perseus file uses.
 * - `manifest.json`: a fingerprint of what V1 produces for each onboarded work.
 *
 * Both are generated by `./morcus.sh library survey --write-snapshot` (see
 * `src/scripts/library/survey_snapshot.ts`) and must not be hand-edited.
 */

/** Increment when the shape of either file changes incompatibly. */
export const AUDIT_SCHEMA_VERSION = 1;

/** The corpus checkout a snapshot was generated from. */
export interface AuditSource {
  /** Always `canonical-latinLit` for now. */
  repo: string;
  /** Full commit sha of the checkout that was surveyed. */
  commit: string;
  /** Whether the checkout had uncommitted changes when surveyed. */
  dirty: boolean;
}

/**
 * The markup one file uses inside its `<body>`. Every list is sorted and
 * de-duplicated. "In a note" means a strict descendant of a `<note>`; the
 * `<note>` element itself counts as outside.
 */
export interface WorkCensus {
  /** Path relative to the corpus root, e.g. `data/phi0448/phi001/....xml`. */
  path: string;
  /** Whether the work is in `ALL_SUPPORTED_WORKS` (library_constants.ts). */
  onboarded: boolean;
  /** Element names outside notes, e.g. `["div", "l", "p"]`. */
  elements: string[];
  /** Element names inside notes. */
  noteElements: string[];
  /** `element@rendValue` outside notes, e.g. `["hi@italic"]`. */
  rends: string[];
  /** `element@rendValue` inside notes. */
  noteRends: string[];
  /** `element@attrName` outside notes, e.g. `["div@n", "l@part"]`. */
  attrs: string[];
  /** `element@attrName` inside notes. */
  noteAttrs: string[];
}

export interface CensusSnapshot {
  schema: number;
  source: AuditSource;
  /** Keyed by work id (file basename without `.xml`), keys sorted. */
  works: Record<string, WorkCensus>;
}

/** A fingerprint of V1's `ProcessedWork2` output for one work. */
export interface WorkFingerprint {
  /** `ProcessedWork2.textParts`, e.g. `["book", "chapter", "section"]`. */
  textParts: string[];
  /** Number of rows. */
  rows: number;
  /** Number of pages. */
  pages: number;
  /** Rows whose id has one entry per text part (`id.length === textParts.length`). */
  citableRows: number;
  /** Id of the first citable row joined with `.`, or `null` if none. */
  firstCitation: string | null;
  /** Id of the last citable row joined with `.`, or `null` if none. */
  lastCitation: string | null;
  /** Number of entries in `ProcessedWork2.notes`. */
  notes: number;
  /**
   * Histogram of emitted content nodes over all rows, keyed by node name, or
   * `name@rend` when the node has a `rend` attribute. Keys sorted.
   */
  nodes: Record<string, number>;
}

export interface FingerprintManifest {
  schema: number;
  source: AuditSource;
  /** Onboarded works only, keyed by work id, keys sorted. */
  works: Record<string, WorkFingerprint>;
}
